mapper.select:
SELECT v.post_id,
       p.title  AS post_title,
       COUNT(*) AS view_count,
       0.0      AS percent
FROM post_view_log v
         LEFT JOIN post p ON v.post_id = p.id
WHERE v.visited_at >= #{startTime}
  AND v.visited_at <= #{endTime}
  AND v.country = #{country}
GROUP BY v.post_id, p.title
ORDER BY view_count DESC
LIMIT #{limit}

SELECT DATE_FORMAT(visited_at, #{format}) AS label,
       COUNT(*)                           AS view_count
FROM post_view_log
WHERE post_id = #{postId}
  AND visited_at >= #{startTime}
  AND visited_at <= #{endTime}
GROUP BY label
ORDER BY label ASC
